		creds, status, err := cliutil.LoadCredentialsWithStatus()
		if err != nil {
			return err
		}
		if status.Refusal != nil && status.Refusal.CredentialsPresent {
			present = true
			where = status.Path
		}
		if status.Loaded && creds != nil && creds.HasValues() {
			present = true
			where = status.Path
		}
