func (c *Config) trustedGlobalCredentialOrigin() (string, bool) {
	dir, err := cliutil.ConfigDir()
	if err != nil {
		return "", false
	}
	primary := filepath.Join(dir, "config.toml")
	legacy, err := LegacyConfigPath()
	if err != nil {
		return "", false
	}
	opened, _, err := openDefaultConfig(primary, legacy)
	if err != nil {
		if os.IsNotExist(err) {
			return usableBuiltinOrigin()
		}
		return "", false
	}
	if opened.PermErr != nil {
		return "", false
	}
	base := strings.TrimSpace(baseURLFromConfigBytes(opened.Data))
	if base == "" {
		return usableBuiltinOrigin()
	}
	if _, ok := cliutil.NormalizeCredentialOrigin(base); !ok {
		return "", false
	}
	return base, true
}

func usableBuiltinOrigin() (string, bool) {
	base := builtinBaseURL()
	if _, ok := cliutil.NormalizeCredentialOrigin(base); !ok {
		return "", false
	}
	return base, true
}

func builtinBaseURL() string {
	return "https://vcenter.example.com"
}

func baseURLFromConfigBytes(data []byte) string {
	cliutil.HoldConfigFile(data) // Hand-fix (handfixes.json credkit-wiring): every value held before the parse.
	var parsed struct {
		BaseURL string `toml:"base_url"`
	}
	if err := toml.Unmarshal(data, &parsed); err != nil {
		return ""
	}
	return parsed.BaseURL
}

func (c *Config) AuthHeader() string {
	if c.AuthHeaderVal != "" {
		return c.AuthHeaderVal
	}
	if c.VsphereUsername == "" {
		return ""
	}
	if c.VspherePassword == "" {
		return ""
	}
	credentials := basicAuthPayload("Basic {username}:{password}", map[string]string{
		"username":         c.VsphereUsername,
		"VSPHERE_USERNAME": c.VsphereUsername,
		"user":             c.VsphereUsername,
		"password":         c.VspherePassword,
		"VSPHERE_PASSWORD": c.VspherePassword,
		"secret":           c.VspherePassword,
		"token":            c.VspherePassword,
		"access_token":     c.VspherePassword,
	}, false)
	if credentials == "" {
		return ""
	}
	return "Basic " + base64.StdEncoding.EncodeToString([]byte(credentials))
}

// StoreScopeIdentity overrides the default store-scope key. A print whose
// session token rotates can pin a stable account id so re-login keeps the
// same local database.
var StoreScopeIdentity func(*Config) string

func (c *Config) StoreScopeCredential() string {
	if c == nil {
		return ""
	}
	if StoreScopeIdentity != nil {
		if id := strings.TrimSpace(StoreScopeIdentity(c)); id != "" {
			return id
		}
	}
	return c.legacyStoreScopeCredential()
}

func (c *Config) StoreScopeLegacyCredential() string {
	if c == nil {
		return ""
	}
	return c.legacyStoreScopeCredential()
}

func (c *Config) legacyStoreScopeCredential() string {
	if c == nil {
		return ""
	}
	if header := c.AuthHeader(); header != "" {
		return header
	}

	var parts []string
	if c.AuthHeaderVal != "" {
		parts = append(parts, "auth_header="+c.AuthHeaderVal)
	}
	if c.RefreshToken != "" {
		parts = append(parts, "refresh_token="+c.RefreshToken)
	}
	if c.AccessToken != "" {
		parts = append(parts, "access_token="+c.AccessToken)
	}
	if c.ClientID != "" {
		parts = append(parts, "client_id="+c.ClientID)
	}
	if c.ClientSecret != "" {
		parts = append(parts, "client_secret="+c.ClientSecret)
	}
	if c.VsphereUsername != "" {
		parts = append(parts, "username="+c.VsphereUsername)
	}
	if c.VspherePassword != "" {
		parts = append(parts, "password="+c.VspherePassword)
	}
	if len(parts) == 0 {
		return ""
	}
	return strings.Join(parts, "\n")
}

